#!/bin/bash
# run_daily_little_prof.sh — Between-survey daily forward for Little Professor.
# Generated by install.py from slopes/little_prof/slope_config.toml
#
# Runs every morning after yesterday's station data is available. Does NOT
# resample, recluster or rewrite SMETs; those happen in run_little_prof.sh
# when a new survey lands.
#
#   1. aws_ingest      fetch the latest station records into the parquet cache
#   2. smet_append     drop yesterday's NWP rows, append observations to now
#   3. nwp_ingest      cut at T_stable, append 48 h of WRF rows
#   4. SNOWPACK daily cycle (snowpack_cycle.py): restart from the daily
#      anchor (yesterday's T_stable, never the +48 h forecast state), run to
#      today's T_stable, save the new anchor, replace the main Zarr after the
#      old anchor, run the forecast into the separate forecast store
#   5. analyze, then scenarios unless --no-scenarios
#
# Usage:
#   ./run_daily_little_prof.sh
#   ./run_daily_little_prof.sh --snapshot 2026-02-15
#   ./run_daily_little_prof.sh --no-nwp
#   ./run_daily_little_prof.sh --no-scenarios
#   ./run_daily_little_prof.sh --dry-run        # report SMET appends only
#
# Cron:
#   0 8 * * *  <project_dir>/run_daily_little_prof.sh >> <log> 2>&1

set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SLOPE_DIR=${SLOPE_DIR:-$PROJECT_DIR/snowpack/little_prof}
export SLOPE_DIR
TOML=$PROJECT_DIR/slopes/little_prof/slope_config.toml
ANALYSIS="python $PROJECT_DIR/src/avachain/analysis_pipeline.py --toml $TOML"
AWS="python $PROJECT_DIR/src/avachain/aws_ingest.py --toml $TOML"
SMET_APPEND="python $PROJECT_DIR/src/avachain/smet_append.py --toml $TOML"
NWP="python $PROJECT_DIR/src/avachain/nwp_ingest.py --toml $TOML"
CYCLE="python $PROJECT_DIR/src/avachain/snowpack_cycle.py --toml $TOML"
VENV=$PROJECT_DIR/.venv/bin/activate
LOG_DIR=$PROJECT_DIR/outputs/little_prof/logs

SNAPSHOT_DATE=""
NO_NWP=0
NO_SCENARIOS=0
DRY_RUN=0

while [[ $# -gt 0 ]]; do
    case "$1" in
        --snapshot)     SNAPSHOT_DATE="$2"; shift 2 ;;
        --no-nwp)       NO_NWP=1; shift ;;
        --no-scenarios) NO_SCENARIOS=1; shift ;;
        --dry-run)      DRY_RUN=1; shift ;;
        *)              echo "Unknown arg: $1"; exit 1 ;;
    esac
done

mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOGFILE="$LOG_DIR/daily_${TIMESTAMP}.log"
exec > >(tee -a "$LOGFILE") 2>&1

echo "============================================================"
echo "  Little Professor — Daily Forward Pipeline"
echo "  Started: $(date)"
echo "  As-of:   ${AVACHAIN_AS_OF:-live}"
echo "  No-NWP:  $NO_NWP   Dry-run: $DRY_RUN"
echo "  Log:     $LOGFILE"
echo "============================================================"
echo ""

cd "$PROJECT_DIR"
source "$VENV"

SECONDS=0
SNAPSHOT_ARG=""
[[ -n "$SNAPSHOT_DATE" ]] && SNAPSHOT_ARG="--snapshot-date $SNAPSHOT_DATE"

echo ">>> Step 1: Fetch latest station data"
step1_start=$SECONDS
$AWS
step1_elapsed=$((SECONDS - step1_start))
echo ""

echo ">>> Step 2: Append observations to cluster SMETs"
step2_start=$SECONDS
if [[ $DRY_RUN -eq 1 ]]; then
    $SMET_APPEND --dry-run
    echo "Dry run: stopping before NWP and SNOWPACK."
    exit 0
fi
$SMET_APPEND
step2_elapsed=$((SECONDS - step2_start))
echo ""

echo ">>> Step 3: NWP forecast extension"
step3_start=$SECONDS
NWP_EDATE=""
STABLE_TS=""
if [[ $NO_NWP -eq 0 ]]; then
    $NWP --lead-hours 48 || echo "    WARNING: nwp_ingest failed — continuing without NWP extension"
    _ts_output=$(python3 -c "
import sys; sys.path.insert(0, '$PROJECT_DIR/src/avachain')
from nwp_ingest import get_stable_ts
from config import ProjectConfig
from pathlib import Path
import pandas as pd
cfg = ProjectConfig.from_toml(Path('$TOML'))
wrf = Path(cfg.wrf_smet_file) if cfg.wrf_smet_file else None
if wrf and wrf.exists():
    ts = get_stable_ts(wrf)
    if ts:
        print(ts.strftime('%Y-%m-%dT%H:%M'),
              (ts + pd.Timedelta(hours=48)).strftime('%Y-%m-%dT%H:%M'))
" 2>/dev/null)
    if [[ -n "$_ts_output" ]]; then
        STABLE_TS=$(echo "$_ts_output" | cut -d' ' -f1)
        NWP_EDATE=$(echo "$_ts_output" | cut -d' ' -f2)
        echo "    T_stable  = $STABLE_TS"
        echo "    NWP EDATE = $NWP_EDATE (T_stable + 48h)"
    else
        echo "    WRF not available; observed run only"
    fi
else
    echo "    Skipped (--no-nwp)"
fi
step3_elapsed=$((SECONDS - step3_start))
echo ""

echo ">>> Step 4: SNOWPACK daily cycle (restart from the daily anchor)"
step4_start=$SECONDS
CYCLE_ARGS="daily"
[[ -n "$STABLE_TS" ]] && CYCLE_ARGS="$CYCLE_ARGS --stable-ts $STABLE_TS --nwp-edate $NWP_EDATE"
$CYCLE $CYCLE_ARGS
step4_elapsed=$((SECONDS - step4_start))
echo ""

echo ">>> Step 5: Analysis + scenario generation"
step5_start=$SECONDS
$ANALYSIS analyze $SNAPSHOT_ARG
if [[ $NO_SCENARIOS -eq 0 ]]; then
    $ANALYSIS scenarios $SNAPSHOT_ARG
else
    echo "    Scenarios skipped (--no-scenarios)"
fi
step5_elapsed=$((SECONDS - step5_start))
echo ""

total_elapsed=$SECONDS
echo "============================================================"
echo "  Daily forward complete"
echo "  Finished: $(date)"
echo "  Total:    $((total_elapsed / 3600))h $(((total_elapsed % 3600) / 60))m $((total_elapsed % 60))s"
echo "  Step 1 (aws_ingest):  $((step1_elapsed / 60))m $((step1_elapsed % 60))s"
echo "  Step 2 (smet_append): $((step2_elapsed / 60))m $((step2_elapsed % 60))s"
echo "  Step 3 (nwp_ingest):  $((step3_elapsed / 60))m $((step3_elapsed % 60))s"
echo "  Step 4 (SNOWPACK):    $((step4_elapsed / 60))m $((step4_elapsed % 60))s"
echo "  Step 5 (analysis):    $((step5_elapsed / 60))m $((step5_elapsed % 60))s"
echo "  Log:       $LOGFILE"
echo "============================================================"
